WITH valid AS (SELECT *, UPPER(dept_name) AS dept_name_upper, COALESCE(budget, 0) AS budget_filled, COALESCE(dept_name, 'UNKNOWN') AS resolved_dept_name FROM departments WHERE dept_name = 'Engineering') SELECT id, dept_name, location, budget, dept_name_upper, budget_filled, ROW_NUMBER() OVER (ORDER BY budget_filled ASC, id ASC) AS row_seq, LEAD(budget, 1) OVER (PARTITION BY location, dept_name ORDER BY budget_filled ASC, id ASC) AS next_budget, AVG(budget_filled) OVER (ORDER BY budget ASC, id ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS budget_filled_avg_2, SUM(budget_filled) OVER (PARTITION BY dept_name ORDER BY budget_filled ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_budget_filled, LAG(budget_filled, 2) OVER (PARTITION BY dept_name, location ORDER BY budget_filled ASC, id ASC) AS prev_budget_filled FROM valid WHERE location IN ('Bangkok', 'Berlin', 'London')
